def check_condition(K, N):
    """Checks if the set K satisfies the condition:
    For any p, q in K, there exists r in K such that p+q-2r is a multiple of N.
    """
    if N <= 0:
        return False # Should not happen

    # Since N=2021 is odd, 2 is invertible mod N.
    # We find 2^(-1) mod N using Fermat's Little Theorem (if N is prime) or extended Euclidean algorithm.
    # N = 2021. We check gcd(2, 2021) = 1.
    # Using standard modular inverse calculation (or noting 2021 = 2*1010 + 1 => 1 = 2021 - 2*1010)
    # 2^(-1) mod 2021 is 1011.
    inv_2 = 1011

    for p in K:
        for q in K:
            # We need r such that 2r == p+q (mod N)
            S = (p + q) % N
            r_required = (S * inv_2) % N

            if r_required not in K:
                return False, p, q, r_required
    return True, None, None, None

